        "why": "AI 인프라 비용과 전력 문제가 커질수록 GPU 대체·보완재로서 국산 NPU의 정책 명분이 커집니다.",
        "kpi": "전력 절감률, 랙당 처리량, 운영비 절감액, 전환 대상 워크로드 수",
